// Customer Orders Retrieval
// Fetches all orders for a customer from Partner Center API

var customerId = input.get("customerId");
var accessToken = input.get("accessToken");

if (!customerId || customerId.trim() === "") {
    log.error("Customer ID is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Customer ID is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else if (!accessToken || accessToken.trim() === "") {
    log.error("Access Token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Access Token is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else {
    try {
        var url = "https://api.partnercenter.microsoft.com/v1/customers/" + customerId.trim() + "/orders";

        log.info("Fetching orders for customer: " + customerId);

        var response = http.get(url, {
            "Authorization": "Bearer " + accessToken.trim(),
            "Accept": "application/json"
        });

        output.set("StatusCode", response.statusCode);
        output.set("Body", response.body);

        if (response.statusCode >= 200 && response.statusCode < 300) {
            var data = json.parse(response.body);

            output.set("TotalCount", data.totalCount || 0);

            var orders = data.items || [];
            output.set("Orders", json.stringify(orders));
            output.set("OrderCount", orders.length);

            // Track statistics
            var statusCounts = {};
            var billingCycles = {};
            var transactionTypes = {};
            var totalLineItems = 0;
            var currencyCode = "";
            var currencySymbol = "";

            for (var i = 0; i < orders.length; i++) {
                var order = orders[i];

                // Count statuses
                var status = order.status || "unknown";
                if (!statusCounts[status]) statusCounts[status] = 0;
                statusCounts[status]++;

                // Count billing cycles
                var cycle = order.billingCycle || "unknown";
                if (!billingCycles[cycle]) billingCycles[cycle] = 0;
                billingCycles[cycle]++;

                // Count transaction types
                var txType = order.transactionType || "unknown";
                if (!transactionTypes[txType]) transactionTypes[txType] = 0;
                transactionTypes[txType]++;

                // Count line items
                if (order.lineItems) {
                    totalLineItems += order.lineItems.length;
                }

                // Capture currency from first order
                if (!currencyCode && order.currencyCode) {
                    currencyCode = order.currencyCode;
                    currencySymbol = order.currencySymbol || "";
                }
            }

            output.set("TotalLineItems", totalLineItems);
            output.set("CurrencyCode", currencyCode);
            output.set("CurrencySymbol", currencySymbol);

            // Build breakdown arrays
            var statusList = [];
            var statusKeys = Object.keys(statusCounts);
            for (var j = 0; j < statusKeys.length; j++) {
                statusList.push({ status: statusKeys[j], count: statusCounts[statusKeys[j]] });
            }
            output.set("StatusBreakdown", json.stringify(statusList));

            var cycleList = [];
            var cycleKeys = Object.keys(billingCycles);
            for (var k = 0; k < cycleKeys.length; k++) {
                cycleList.push({ cycle: cycleKeys[k], count: billingCycles[cycleKeys[k]] });
            }
            output.set("BillingCycleBreakdown", json.stringify(cycleList));

            var txList = [];
            var txKeys = Object.keys(transactionTypes);
            for (var m = 0; m < txKeys.length; m++) {
                txList.push({ type: txKeys[m], count: transactionTypes[txKeys[m]] });
            }
            output.set("TransactionTypeBreakdown", json.stringify(txList));

            // Get most recent order info
            if (orders.length > 0) {
                var latest = orders[0];
                output.set("LatestOrderId", latest.id || "");
                output.set("LatestOrderDate", latest.creationDate || "");
                output.set("LatestOrderStatus", latest.status || "");
                output.set("LatestOrderBillingCycle", latest.billingCycle || "");
            } else {
                output.set("LatestOrderId", "");
                output.set("LatestOrderDate", "");
                output.set("LatestOrderStatus", "");
                output.set("LatestOrderBillingCycle", "");
            }

            output.set("HasErrors", false);
            output.set("ErrorMessage", "");

            log.info("Successfully retrieved " + orders.length + " orders with " + totalLineItems + " line items");
            tags.trigger("success");
        } else {
            var errorMsg = "API returned status " + response.statusCode;
            try {
                var errorBody = json.parse(response.body);
                if (errorBody.message) errorMsg = errorBody.message;
                else if (errorBody.error_description) errorMsg = errorBody.error_description;
            } catch (e) {
                if (response.body) errorMsg = response.body.substring(0, 500);
            }

            log.error("Failed to retrieve orders: " + errorMsg);
            output.set("HasErrors", true);
            output.set("ErrorMessage", errorMsg);
            tags.trigger("error");
        }
    } catch (ex) {
        log.error("Request failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", "Request failed: " + ex.message);
        output.set("StatusCode", 0);
        tags.trigger("error");
    }
}
